import{_ as o,o as i,c as a,ag as e}from"./chunks/framework.DMyGj-H5.js";const l="/ems_simulate/doc-img/point/change-tracking/1.png",n="/ems_simulate/doc-img/point/change-tracking/2.png",p="/ems_simulate/doc-img/point/change-tracking/3.png",c="/ems_simulate/doc-img/point/change-tracking/4.png",s="/ems_simulate/doc-img/point/change-tracking/5.png",r="/ems_simulate/doc-img/point/change-tracking/6.png",q=JSON.parse('{"title":"变化回溯","description":"","frontmatter":{},"headers":[],"relativePath":"guide/point/change-tracking.md","filePath":"guide/point/change-tracking.md","lastUpdated":1771854974000}'),g={name:"guide/point/change-tracking.md"};function u(m,t,_,d,k,h){return i(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="变化回溯" tabindex="-1">变化回溯 <a class="header-anchor" href="#变化回溯" aria-label="Permalink to &quot;变化回溯&quot;">​</a></h1><p>本章节介绍测点值的变化回溯功能。系统会记录测点值发生变化的原因和详细信息，以便于随时排查问题和追踪数据来源。</p><h2 id="变化原因说明" tabindex="-1">变化原因说明 <a class="header-anchor" href="#变化原因说明" aria-label="Permalink to &quot;变化原因说明&quot;">​</a></h2><p>系统记录的测点变化原因主要包括以下几种，每种原因不仅代表了值的更新源，还反映了系统的不同交互场景：</p><ul><li><p><strong>manual</strong>: 手动置值</p><ul><li><p>场景：用户通过 Web 界面或命令行工具手动输入或修改了该测点的值。</p><blockquote><p><img src="'+l+'" alt=""></p></blockquote></li></ul></li><li><p><strong>simulation</strong>: 自动模拟</p><ul><li><p>场景：该测点配置了模拟规则（如随机数、正弦波等），系统后台运行模拟任务更新了它的值。</p><blockquote><p><img src="'+n+'" alt=""></p></blockquote></li></ul></li><li><p><strong>mapping</strong>: 关联测点更新</p><ul><li><p>场景：该测点的状态或数值受到其它配置了映射关系的测点影响，同步完成了联动更新。</p><p>举例：yc1=yc2*10+5</p><blockquote><p><img src="'+p+'" alt=""></p></blockquote><p>查看变化回溯</p><blockquote><p><img src="'+c+'" alt=""></p></blockquote></li></ul></li><li><p><strong>protocol</strong>: 协议远程修改</p><ul><li><p>场景：作为从机运行时，来自主站（如客户端 SCADA 系统）通过通讯协议（Modbus 等）对当前测点发起了写操作。</p><blockquote><p><img src="'+s+'" alt=""></p></blockquote></li></ul></li><li><p><strong>client_read</strong>: 客户端读取</p><ul><li><p>场景：作为主机运行时，EMS Simulate 模拟器从真实下级设备成功读取到了测点最新数据并完成同步。</p><blockquote><p><img src="'+r+'" alt=""></p></blockquote></li></ul></li></ul>',5)])])}const f=o(g,[["render",u]]);export{q as __pageData,f as default};
